package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitable;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonStringFormatVisitor;
import com.fasterxml.jackson.databind.jsonschema.SchemaAware;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import com.fasterxml.jackson.databind.ser.BeanProperty;
import com.fasterxml.jackson.databind.ser.BeanSerializer;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.JsonSerializer;
import com.fasterxml.jackson.databind.ser.impl.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.ser.std.JsonValueSerializer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.LinkedHashSet;
import java.util.Set;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class JsonValueSerializer_acceptJsonFormatVisitor_TriageGen2Test {

    private JsonValueSerializer serializer;
    private JsonFormatVisitorWrapper visitor;
    private JavaType typeHint;
    private SerializerProvider provider;
    private BeanProperty property;

    // Since the fields _accessorMethod and _valueSerializer are private, 
    // we use reflection to inject them for testing purposes.

    private static class TestEnum {
        public enum Value { A, B }
    }

    @Before
    public void setUp() {
        serializer = mock(JsonValueSerializer.class, spy(new JsonValueSerializer(null, null, false)));
        visitor = mock(JsonFormatVisitorWrapper.class);
        typeHint = mock(JavaType.class);
        provider = mock(SerializerProvider.class);
        property = mock(BeanProperty.class);

        when(visitor.getProvider()).thenReturn(provider);
    }

    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private void setAccessorMethod(JsonValueSerializer target, Method method) throws Exception {
        setPrivateField(target, "_accessorMethod", method);
    }

    private void setValueSerializer(JsonValueSerializer target, JsonSerializer<Object> ser) throws Exception {
        setPrivateField(target, "_valueSerializer", ser);
    }

    @Test
    public void testAcceptJsonFormatVisitor_EnumHandling_ReturnsTrue() throws Exception {
        // Setup: Declaring class is an Enum
        Method enumMethod = TestEnum.Value.class.getMethod("values");
        setAccessorMethod(serializer, enumMethod);

        // We need to spy on the real object to trigger the protected _acceptJsonFormatVisitorForEnum
        JsonValueSerializer spySerializer = spy(new JsonValueSerializer(null, null, false));
        setAccessorMethod(spySerializer, enumMethod);

        doReturn(true).when(spySerializer)._acceptJsonFormatVisitorForEnum(any(), any(), eq(TestEnum.Value.class));

        spySerializer.acceptJsonFormatVisitor(visitor, typeHint);

        verify(spySerializer)._acceptJsonFormatVisitorForEnum(visitor, typeHint, TestEnum.Value.class);
        verify(visitor, never()).getProvider();
    }

    @Test
    public void testAcceptJsonFormatVisitor_NonEnum_WithExistingSerializer() throws Exception {
        // Setup: Not an enum, and _valueSerializer is NOT null
        Method nonEnumMethod = String.class.getMethod("length");
        setAccessorMethod(serializer, nonEnumMethod);

        JsonSerializer<Object> mockSer = mock(JsonSerializer.class);
        setValueSerializer(serializer, mockSer);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        verify(mockSer).acceptJsonFormatVisitor(visitor, null);
        verify(visitor, never()).getProvider();
    }

    @Test
    public void testAcceptJsonFormatVisitor_NonEnum_FindSerializerSuccess() throws Exception {
        // Setup: Not an enum, _valueSerializer is null, but provider finds one
        Method nonEnumMethod = String.class.getMethod("length");
        setAccessorMethod(serializer, nonEnumMethod);
        setValueSerializer(serializer, null);

        JavaType type = mock(JavaType.class);
        when(nonEnumMethod.getDeclaringClass()).thenReturn(String.class);
        when(nonEnumMethod.getType()).thenReturn(type);

        JsonSerializer<Object> foundSer = mock(JsonSerializer.class);
        when(provider.findTypedValueSerializer(eq(type), eq(false), any())).thenReturn(foundSer);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        verify(foundSer).acceptJsonFormatVisitor(visitor, null);
    }

    @Test
    public void testAcceptJsonFormatVisitor_NonEnum_FindSerializerFail() throws Exception {
        // Setup: Not an enum, _valueSerializer is null, and provider returns null
        Method nonEnumMethod = String.class.getMethod("length");
        setAccessorMethod(serializer, nonEnumMethod);
        setValueSerializer(serializer, null);

        JavaType type = mock(JavaType.class);
        when(nonEnumMethod.getDeclaringClass()).thenReturn(String.class);
        when(nonEnumMethod.getType()).thenReturn(type);

        when(provider.findTypedValueSerializer(eq(type), eq(false), any())).thenReturn(null);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        verify(visitor).expectAnyFormat(typeHint);
    }

    @Test(expected = JsonMappingException.class)
    public void testAcceptJsonFormatVisitor_ThrowsException() throws Exception {
        // Setup: Simulate exception during visitor call
        Method nonEnumMethod = String.class.getMethod("length");
        setAccessorMethod(serializer, nonEnumMethod);

        JsonSerializer<Object> mockSer = mock(JsonSerializer.class);
        setValueSerializer(serializer, mockSer);

        doThrow(new JsonMappingException(null, "error")).when(mockSer).acceptJsonFormatVisitor(any(), any());

        serializer.acceptJsonFormatVisitor(visitor, typeHint);
    }
}
